package main
import("testing";"path/filepath";"database/sql";"context";"os";"net/http/httptest";"strings";"encoding/json";"time")
func TestLibraryReadOnly(t *testing.T){p:=filepath.Join(t.TempDir(),"fixture.sqlite3");db,e:=sql.Open(sqliteDriver,p);if e!=nil{t.Fatal(e)};for _,table:=range []string{"video","page","page_occurrence","utterance","asset","page_image","audio_chunk"}{if _,e=db.Exec("CREATE TABLE "+table+"(id text)");e!=nil{t.Fatal(e)}};db.Close();if e=openLibrary(p);e!=nil{t.Fatal(e)};ro,_,_:=getLibrary();if _,e=ro.Exec("INSERT INTO video VALUES('write-probe')");e==nil{t.Fatal("write was allowed")};var mode int;ro.QueryRow("PRAGMA query_only").Scan(&mode);if mode!=1{t.Fatal(mode)};ro.Close();libraryState.Lock();libraryState.db=nil;libraryState.Unlock()}
func TestRealLibraryReadPaths(t *testing.T){p:=os.Getenv("TEST_LIBRARY_DB");if p==""{t.Skip("read-only integration database not configured")};before,e:=os.Stat(p);if e!=nil{t.Fatal(e)};if e=openLibrary(p);e!=nil{t.Fatal(e)};db,_,_:=getLibrary();ctx,cancel:=context.WithTimeout(context.Background(),60*time.Second);defer cancel();var n int;if e=db.QueryRow("SELECT count(*) FROM video").Scan(&n);e!=nil||n!=36{t.Fatalf("count %d %v",n,e)};for _,id:=range []string{"lijing:R12","songxiaofei:R12","f1_zhaoyi:R09"}{p,e:=enrichPage(ctx,db,id);if e!=nil{t.Fatal(e)};if p["id"]!=id{t.Fatal(p)}}
 a:=&App{};w:=httptest.NewRecorder();a.librarySearch(w,httptest.NewRequest("POST","/api/search",strings.NewReader(`{"q":"宋晓菲和李静的人工智能教学有什么区别"}`)));if w.Code!=200{t.Fatal(w.Body.String())};var out struct{Pages []struct{Tag string `json:"tag"`} `json:"pages"`};if e=json.Unmarshal(w.Body.Bytes(),&out);e!=nil{t.Fatal(e)};tags:=map[string]bool{};for _,p:=range out.Pages{tags[p.Tag]=true};if !tags["lijing"]||!tags["songxiaofei"]{t.Fatalf("missing comparison source: %v",tags)};after,_:=os.Stat(p);if after.Size()!=before.Size()||!after.ModTime().Equal(before.ModTime()){t.Fatal("source database changed")};t.Logf("36 sessions; cross-source result %v; file unchanged",tags)
}
